// ============================================================================
// External RAM Instance
// ============================================================================

// Global SRAM instance (set by gui_loader_set_sram)
static SPISRAM* global_sram_instance = nullptr;

/**
 * Set the external SRAM instance to use for GUI loading
 * 
 * @param sram Pointer to initialized SPISRAM instance
 */
void gui_loader_set_sram(SPISRAM* sram) {
    global_sram_instance = sram;
    
    // Initialize external RAM loader if SRAM is provided
    if (sram) {
        gui_external_ram_init(sram);
    }
}

/**
 * Get the current SRAM instance
 * 
 * @return Pointer to SPISRAM instance, or NULL if not set
 */
SPISRAM* gui_loader_get_sram() {
    return global_sram_instance;
}

