// ============================================================================
// Modified: Load GUI with External RAM Support
// ============================================================================

void* gui_loader_load_from_sd(const char* filename) {
    #if GUI_LOADER_USE_EXTERNAL_RAM_BY_DEFAULT && GUI_LOADER_CHECK_MEMORY_BEFORE_LOAD
    
    // If external RAM is available, try to load there first
    if (global_sram_instance) {
        // Check if file exists and get size
        char full_path[128];
        snprintf(full_path, sizeof(full_path), "/gui/%s", filename);
        
        int file_size = gui_loader_get_size(full_path);
        if (file_size > 0 && file_size <= GUI_JSON_MAX_SIZE) {
            // Check if there's space in external RAM
            if (gui_external_ram_has_space(global_sram_instance, file_size)) {
                // Load directly into external RAM
                if (gui_external_ram_load_from_sd(full_path, global_sram_instance)) {
                    // Parse from external RAM
                    return gui_external_ram_parse(global_sram_instance);
                }
            }
        }
    }
    
    #endif
    
    // Fallback: Load into internal RAM (original behavior)
    char buffer[GUI_LOADER_MAX_SIZE];
    int bytes_read = gui_loader_load(filename, buffer, sizeof(buffer));
    
    if (bytes_read <= 0) {
        return NULL;
    }
    
    return gui_loader_parse_json(buffer);
}

/**
 * Load GUI from SD card into external RAM
 * 
 * @param filename GUI filename
 * @return Pointer to GUI structure, or NULL on error
 * @note GUI data is stored in external RAM, but parsed widgets use internal pools
 */
void* gui_loader_load_from_sd_to_external_ram(const char* filename) {
    if (!global_sram_instance) {
        // No external RAM configured, use internal
        return gui_loader_load_from_sd(filename);
    }
    
    char full_path[128];
    snprintf(full_path, sizeof(full_path), "/gui/%s", filename);
    
    // Load into external RAM
    if (gui_external_ram_load_from_sd(full_path, global_sram_instance)) {
        // Parse from external RAM
        return gui_external_ram_parse(global_sram_instance);
    }
    
    return NULL;
}

/**
 * Load GUI from WebDAV into external RAM
 * 
 * @param filename GUI filename
 * @return Pointer to GUI structure, or NULL on error
 */
void* gui_loader_load_from_webdav_to_external_ram(const char* filename) {
    if (!global_sram_instance) {
        // No external RAM configured, use internal
        char buffer[GUI_LOADER_MAX_SIZE];
        int bytes_read = gui_loader_load_from_webdav(filename, buffer, sizeof(buffer));
        if (bytes_read <= 0) return NULL;
        return gui_loader_parse_json(buffer);
    }
    
    // Load into external RAM
    if (gui_external_ram_load_from_webdav(filename, global_sram_instance)) {
        // Parse from external RAM
        return gui_external_ram_parse(global_sram_instance);
    }
    
    return NULL;
}

