bool gui_loader_validate_json(const char* json) {
    // Validate JSON against schema
    // For now, just check if it's non-empty
    if (json == NULL || strlen(json) == 0) {
        return false;
    }
    
    // Check for basic structure
    // This is a very simple check - real implementation would use a JSON schema validator
    return strstr(json, "\"version\"") != NULL &&
           strstr(json, "\"widgets\"") != NULL &&
           strstr(json, "\"size\"") != NULL;
}

// ============================================================================
// Hybrid Loading Functions
// ============================================================================

/**
 * Load GUI with automatic external RAM usage
 * Tries external RAM first, falls back to internal RAM
 * 
 * @param filename GUI filename
 * @param use_external_ram If true, try external RAM first
 * @return Pointer to GUI structure, or NULL on error
 */
void* gui_loader_load_auto(const char* filename, bool use_external_ram) {
    if (use_external_ram && global_sram_instance) {
        // Try external RAM first
        void* gui = gui_loader_load_from_sd_to_external_ram(filename);
        if (gui) {
            return gui;
        }
    }
    
    // Fall back to internal RAM
    return gui_loader_load_from_sd(filename);
}

/**
 * Force reload GUI from SD card
 * If GUI was loaded into external RAM, reload it there
 * Otherwise, reload into internal RAM
 * 
 * @param filename GUI filename
 * @return Pointer to GUI structure, or NULL on error
 */
void* gui_loader_reload(const char* filename) {
    // First, clear any existing GUI in external RAM
    if (global_sram_instance && gui_external_ram_has_gui(global_sram_instance)) {
        gui_external_ram_clear(global_sram_instance);
    }
    
    // Reload
    return gui_loader_load_auto(filename, true);
}

// ============================================================================
// GUI Storage Information
// ============================================================================

/**
 * Check where a GUI is currently stored
 * 
 * @return true if GUI is stored in external RAM, false if in internal RAM
 */
bool gui_loader_is_in_external_ram() {
    if (!global_sram_instance) {
        return false;
    }
    return gui_external_ram_has_gui(global_sram_instance);
}

/**
 * Get GUI storage location as string
 * 
 * @return "External RAM" or "Internal RAM"
 */
const char* gui_loader_get_storage_location() {
    return gui_loader_is_in_external_ram() ? "External RAM" : "Internal RAM";
}

/**
 * Get memory usage information
 * 
 * @param total_ram Output: Total RAM available
 * @param used_ram Output: Used RAM for GUI
 * @param is_external Output: true if using external RAM
 */
void gui_loader_get_memory_info(uint32_t* total_ram, uint32_t* used_ram, bool* is_external) {
    if (total_ram) *total_ram = 0;
    if (used_ram) *used_ram = 0;
    if (is_external) *is_external = false;
    
    if (!global_sram_instance) {
        return;
    }
    
    if (is_external) {
        *is_external = gui_external_ram_has_gui(global_sram_instance);
    }
    
    if (global_sram_instance) {
        if (total_ram) {
            *total_ram = global_sram_instance->getSize();
        }
        if (used_ram) {
            *used_ram = gui_external_ram_get_usage(global_sram_instance);
        }
    }
}
